'use strict';
// Separate post-run executable; no provider import or calls.
const assert=require('node:assert/strict'),fs=require('node:fs'),{createHash}=require('node:crypto');
const {packets,PIN}=require('./sourceMeaningActual18'),{requestFor,classify}=require('./sourceMeaningDiagnostic'),historical=require('./pricingDirectiveGroupsActualJudge');
const LABELS='tests/release-inputs/source-meaning18-independent-labels-2026-09-27.json',LABEL_PIN='473d391c4b1601d24333ee6c76287c7f740ae96e2204d4b460378a8f345507cb',sha=x=>createHash('sha256').update(x).digest('hex');
async function score(result,inputs,labels){assert.equal(result.status,'predictions-complete');assert.equal(result.technicalComplete,true);assert.deepEqual(result.unattempted,[]);assert.equal(result.creditAuthorized,false);for(const call of result.calls){assert.equal(Object.hasOwn(call,'errorCode'),false);assert.equal(call.responseBytes,Buffer.byteLength(call.response));assert.equal(call.observedBytes,call.responseBytes);}assert.equal(result.inputSha256,PIN);assert.deepEqual(result.model,{name:historical.MODEL,digest:historical.DIGEST});assert.equal(result.cases.length,18);assert.equal(result.calls.length,19);assert.deepEqual(result.cases.map(x=>x.id),inputs.map(x=>x.id));assert.deepEqual(labels.labels.map(x=>x.id),inputs.map(x=>x.id));const tags=result.calls.filter(x=>x.kind==='metadata');assert.equal(tags.length,1);assert.equal(tags[0],result.calls[0]);assert.equal(tags[0].index,1);assert.equal(tags[0].caseId,null);assert.equal(tags[0].request,null);assert.equal(tags[0].requestSha256,sha(''));assert.equal(tags[0].httpStatus,200);assert.equal(tags[0].status,'returned');assert.equal(sha(tags[0].response),tags[0].responseSha256);assert.equal(JSON.parse(tags[0].response).models.find(x=>x.name===historical.MODEL)?.digest,historical.DIGEST);const scores=[];for(let i=0;i<18;i++){const row=result.cases[i],input=inputs[i],calls=result.calls.filter(x=>x.caseId===input.id);assert.equal(calls.length,1);const call=calls[0];assert.equal(call,result.calls[i+1]);assert.equal(call.index,i+2);assert.equal(call.kind,'inference');assert.equal(call.status,'returned');assert.equal(call.httpStatus,200);assert.equal(sha(call.request),call.requestSha256);assert.equal(sha(call.response),call.responseSha256);const request=requestFor({source:input.source}),sent=JSON.parse(call.request);assert.equal(sent.model,historical.MODEL);assert.deepEqual(sent.messages,request.messages);assert.deepEqual(sent.format,request.schema);assert.deepEqual(row.result.request,request);assert.equal(row.result.sourceSha256,request.sourceSha256);const raw=historical.reconstruct(call.response),parsed=await classify({source:input.source},async()=>raw);assert.deepEqual(row.result,parsed);assert.equal(row.result.calls,1);scores.push({id:input.id,observed:parsed.decision,expected:labels.labels[i].decision,match:parsed.status==='observed'&&parsed.decision===labels.labels[i].decision});}return {diagnosticOnly:true,creditAuthorized:false,semanticAccepted:result.technicalComplete===true&&scores.every(x=>x.match),scores};}
async function main(){const labelsBytes=fs.readFileSync(LABELS);assert.equal(sha(labelsBytes),LABEL_PIN);const resultBytes=fs.readFileSync(process.argv[2]);assert(resultBytes.length<=90*1024*1024);const result=await score(JSON.parse(resultBytes),packets(process.cwd()),JSON.parse(labelsBytes));fs.writeFileSync(process.argv[3],JSON.stringify({predictionSha256:sha(resultBytes),labelSha256:LABEL_PIN,...result},null,2)+'\n',{mode:0o600});if(!result.semanticAccepted)process.exitCode=1;}
module.exports={score,LABELS,LABEL_PIN};if(require.main===module)main().catch(()=>{console.error('Source-only scoring unavailable');process.exitCode=1;});
